from flask import Flask, request, jsonify
import sqlite3
from pathlib import Path
from datetime import datetime
import base64

APP_DIR = Path(__file__).resolve().parent
DB_PATH = APP_DIR / "storycore_vvip.db"
ASSET_DIR = APP_DIR / "storycore_assets"
ASSET_DIR.mkdir(exist_ok=True)

HTML = base64.b64decode("").decode("utf-8")

app = Flask(__name__)

def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db()
    conn.executescript("""
CREATE TABLE IF NOT EXISTS projects(
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 title TEXT NOT NULL,
 idea TEXT NOT NULL,
 style TEXT NOT NULL,
 ratio TEXT NOT NULL,
 quality TEXT NOT NULL,
 duration TEXT NOT NULL,
 created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS prompts(
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 name TEXT NOT NULL,
 text TEXT NOT NULL,
 created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS assets(
 id INTEGER PRIMARY KEY AUTOINCREMENT,
 name TEXT NOT NULL,
 filename TEXT NOT NULL,
 size INTEGER NOT NULL,
 created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS settings(
 key TEXT PRIMARY KEY,
 value TEXT NOT NULL
);
""")
    defaults = {
        "theme":"midnight","motion":"1","glow":"1","particles":"1",
        "grid":"1","compact":"0","sound":"0","autoplay":"0"
    }
    for key, value in defaults.items():
        conn.execute("INSERT OR IGNORE INTO settings(key,value) VALUES(?,?)",(key,value))
    conn.commit()
    conn.close()

def as_dict(row):
    return dict(row) if row else None

@app.route("/")
def home():
    return HTML

@app.get("/api/projects")
def list_projects():
    conn=get_db()
    rows=conn.execute("SELECT * FROM projects ORDER BY id DESC").fetchall()
    conn.close()
    return jsonify([as_dict(r) for r in rows])

@app.post("/api/projects")
def add_project():
    data=request.get_json(silent=True) or {}
    idea=str(data.get("idea","")).strip()
    if not idea:
        return jsonify({"error":"Story idea is required"}),400
    conn=get_db()
    cur=conn.execute(
        "INSERT INTO projects(title,idea,style,ratio,quality,duration,created_at) VALUES(?,?,?,?,?,?,?)",
        (
            str(data.get("title","Untitled Story")).strip() or "Untitled Story",
            idea,
            str(data.get("style","3D cinematic cartoon")),
            str(data.get("ratio","16:9")),
            str(data.get("quality","480p")),
            str(data.get("duration","10 sec")),
            datetime.now().isoformat()
        )
    )
    conn.commit()
    row=conn.execute("SELECT * FROM projects WHERE id=?",(cur.lastrowid,)).fetchone()
    conn.close()
    return jsonify(as_dict(row)),201

@app.get("/api/projects/<int:item_id>")
def one_project(item_id):
    conn=get_db()
    row=conn.execute("SELECT * FROM projects WHERE id=?",(item_id,)).fetchone()
    conn.close()
    if not row:
        return jsonify({"error":"Project not found"}),404
    return jsonify(as_dict(row))

@app.delete("/api/projects/<int:item_id>")
def remove_project(item_id):
    conn=get_db()
    conn.execute("DELETE FROM projects WHERE id=?",(item_id,))
    conn.commit()
    conn.close()
    return jsonify({"ok":True})

@app.get("/api/prompts")
def list_prompts():
    conn=get_db()
    rows=conn.execute("SELECT * FROM prompts ORDER BY id DESC").fetchall()
    conn.close()
    return jsonify([as_dict(r) for r in rows])

@app.post("/api/prompts")
def add_prompt():
    data=request.get_json(silent=True) or {}
    name=str(data.get("name","")).strip()
    text=str(data.get("text","")).strip()
    if not name or not text:
        return jsonify({"error":"Name and prompt are required"}),400
    conn=get_db()
    cur=conn.execute("INSERT INTO prompts(name,text,created_at) VALUES(?,?,?)",
                     (name,text,datetime.now().isoformat()))
    conn.commit()
    row=conn.execute("SELECT * FROM prompts WHERE id=?",(cur.lastrowid,)).fetchone()
    conn.close()
    return jsonify(as_dict(row)),201

@app.delete("/api/prompts/<int:item_id>")
def remove_prompt(item_id):
    conn=get_db()
    conn.execute("DELETE FROM prompts WHERE id=?",(item_id,))
    conn.commit()
    conn.close()
    return jsonify({"ok":True})

@app.get("/api/assets")
def list_assets():
    conn=get_db()
    rows=conn.execute("SELECT * FROM assets ORDER BY id DESC").fetchall()
    conn.close()
    return jsonify([as_dict(r) for r in rows])

@app.post("/api/assets")
def upload_assets():
    files=request.files.getlist("files")
    if not files:
        return jsonify({"error":"No files selected"}),400
    conn=get_db()
    for item in files:
        if not item.filename:
            continue
        safe=Path(item.filename).name
        filename=datetime.now().strftime("%Y%m%d_%H%M%S_%f_")+safe
        target=ASSET_DIR/filename
        item.save(target)
        conn.execute(
            "INSERT INTO assets(name,filename,size,created_at) VALUES(?,?,?,?)",
            (safe,filename,target.stat().st_size,datetime.now().isoformat())
        )
    conn.commit()
    conn.close()
    return jsonify({"ok":True})

@app.delete("/api/assets/<int:item_id>")
def remove_asset(item_id):
    conn=get_db()
    row=conn.execute("SELECT filename FROM assets WHERE id=?",(item_id,)).fetchone()
    if row:
        try:
            (ASSET_DIR/row["filename"]).unlink(missing_ok=True)
        except OSError:
            pass
        conn.execute("DELETE FROM assets WHERE id=?",(item_id,))
        conn.commit()
    conn.close()
    return jsonify({"ok":True})

@app.get("/api/settings")
def read_settings():
    conn=get_db()
    rows=conn.execute("SELECT key,value FROM settings").fetchall()
    conn.close()
    result={}
    for row in rows:
        result[row["key"]] = row["value"] if row["key"]=="theme" else row["value"]=="1"
    return jsonify(result)

@app.put("/api/settings")
def write_settings():
    data=request.get_json(silent=True) or {}
    allowed=["theme","motion","glow","particles","grid","compact","sound","autoplay"]
    conn=get_db()
    for key in allowed:
        if key not in data:
            continue
        value=str(data[key]) if key=="theme" else ("1" if bool(data[key]) else "0")
        conn.execute(
            "INSERT INTO settings(key,value) VALUES(?,?) "
            "ON CONFLICT(key) DO UPDATE SET value=excluded.value",
            (key,value)
        )
    conn.commit()
    conn.close()
    return jsonify({"ok":True})

